preConditionHook:
// RANGE OUTSIDE PRIOR RANGE FRACTION (Brian's notes I1). The part of this
// bar's high-low range lying above the prior priorBars-bar high plus the part
// below the prior low is at least minOutsideFraction of the bar's range: a
// trend bar (negate for a consolidation bar). Direction-agnostic. A product,
// not a quotient (EL raises on a zero divisor), and the outside part must be
// positive, so a zero-range bar inside the prior range does not pass.
// EL's Highest(...)[1] over priorBars: Extremes over bars 1 .. priorBars. The two
// clamps are if-statements rather than MaxList, whose scope in the register is
// selection among tick-grid prices.
hh = high[1];
ll = low[1];
for (int i = 1; i < (int)priorBars; ++i) {
    if (el_gt(high[1 + i], hh)) hh = high[1 + i];
    if (el_lt(low[1 + i], ll)) ll = low[1 + i];
}
outAbove = 0.0;
outBelow = 0.0;
if (el_gt(high[0], hh)) outAbove = high[0] - hh;
if (el_lt(low[0], ll)) outBelow = ll - low[0];
outPart = outAbove + outBelow;
